export function item(n=30):DateQueryItem{return {asset_id:id(n),name:'synthetic-'+n,created_at:'2026-10-02T00:00:00Z',assessment:{asset_id:id(n),tenant_id:context.tenantId,asset_version:1,metadata_version:null,observed_at:'2026-10-02T16:00:00Z',as_of_date:'2026-10-03',timezone:'Asia/Shanghai',policy_version:'contract-m3-10-date-v1',scope:'RECORDED_DATE_ASSESSMENT_ONLY',source:'postgresql',recorded_dates_source:'MANUAL_ASSET_METADATA',verification_status:null,coverage_verified:false,warranty_expiry:unknown(),overdue_service_date:unknown(),warranty_start:null,warranty_provider:null,hazard_lookup_status:'NOT_IMPLEMENTED',notification_lookup_status:'NOT_IMPLEMENTED',actions_this_request:{hazard_creation:'NOT_REQUESTED',notification:'NOT_REQUESTED',asset_updated:false}}}}
export function page(items=[item()],more=false):DateQueryPage{return {items,has_more:more,next_before_created_at:more?items.at(-1)!.created_at:null,next_before_id:more?items.at(-1)!.asset_id:null,next_expected_reference_date:more?'2026-10-03':null,date_field:'warranty_expiry',window:'UNKNOWN',filters:{},reference_date:'2026-10-03',observed_at:'2026-10-02T16:00:00Z',timezone:'Asia/Shanghai',source:'postgresql',scope:'CURRENT_TENANT_INTERNAL_MANUAL_DATE_FILTER',page_size_limit:100,pagination_consistency:'CURRENT_REQUEST_SNAPSHOT_ONLY',metadata_change_semantics:'NOT_FROZEN_ACROSS_PAGES'}}
